import { readFile, writeFile } from "node:fs/promises";

const root = new URL("../", import.meta.url);
const bundleUrl = new URL("supabase/launch_bundle.sql", root);
const marker = "-- BEGIN GENERATED RELEASE DELTAS";
const migrationNames = [
  "20260723105000_company_workspace_dependencies.sql",
  "20260725210000_listing_owner_integrity.sql",
  "20260725220000_storage_update_ownership.sql",
  "20260727170000_harden_identity_tenant_integrity.sql",
  "20260727173000_atomic_checkout_orders.sql",
  "20260728000050_payout_processing_enum.sql",
  "20260728000100_paymob_financial_boundaries.sql",
  "20260728000300_manual_subscription_payments.sql",
  "20260729090000_private_order_payment_proofs.sql",
];

let bundle = await readFile(bundleUrl, "utf8");
bundle = bundle.split(marker, 1)[0].trimEnd();
bundle = bundle.replace(/\nCOMMIT;\s*$/i, "");

const deltas = [];
for (const name of migrationNames) {
  const migration = await readFile(new URL(`supabase/migrations/${name}`, root), "utf8");
  const body = migration
    .replace(/^\s*BEGIN;\s*$/gim, "")
    .replace(/^\s*COMMIT;\s*$/gim, "")
    .trim();
  deltas.push(`-- Source: supabase/migrations/${name}\n${body}`);
}

await writeFile(
  bundleUrl,
  `${bundle}\n\n${marker}\n-- Generated by scripts/build-launch-bundle.mjs. Do not edit this section manually.\n\n${deltas.join(
    "\n\n",
  )}\n\nCOMMIT;\n`,
);
